package ro.leo.visual;
import android.app.*;import android.content.*;import android.os.*;import java.net.*;
/** Explicit, 15-minute Wi-Fi session; never starts at boot and never exposes a shell. */
public final class CompanionService extends Service {
 static volatile CompanionService instance;CompanionServer server;String address="",secret="";final Handler timer=new Handler();boolean registered;
 static InetAddress wifi(Context c)throws Exception{android.net.ConnectivityManager cm=(android.net.ConnectivityManager)c.getSystemService(CONNECTIVITY_SERVICE);for(android.net.Network n:cm.getAllNetworks()){android.net.NetworkCapabilities cap=cm.getNetworkCapabilities(n);android.net.LinkProperties lp=cm.getLinkProperties(n);if(cap!=null&&lp!=null&&cap.hasTransport(android.net.NetworkCapabilities.TRANSPORT_WIFI))for(android.net.LinkAddress a:lp.getLinkAddresses())if(a.getAddress() instanceof Inet4Address&&!a.getAddress().isLoopbackAddress()&&!a.getAddress().isLinkLocalAddress())return a.getAddress();}throw new java.io.IOException("Connect Nokia to Wi-Fi first");}
 final BroadcastReceiver connectivity=new BroadcastReceiver(){public void onReceive(Context c,Intent i){try{if(server!=null&&!wifi(c).equals(server.server.getInetAddress()))stopSelf();}catch(Exception e){stopSelf();}}};
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int f,int id){if(i!=null&&"stop".equals(i.getAction())){stopSelf();return START_NOT_STICKY;}NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("leo-companion","Leo Companion",NotificationManager.IMPORTANCE_LOW));PendingIntent stop=PendingIntent.getService(CompanionService.this,0,new Intent(CompanionService.this,CompanionService.class).setAction("stop"),0);startForeground(737,new Notification.Builder(CompanionService.this,"leo-companion").setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("Leo Companion · Wi-Fi").setContentText("15-minute file exchange session").setContentIntent(PendingIntent.getActivity(CompanionService.this,0,new Intent(CompanionService.this,CompanionActivity.class),0)).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Stop",stop).build());if(server==null)try{secret=CompanionServer.token();InetAddress bind=wifi(CompanionService.this);server=new CompanionServer(CompanionService.this,bind,18764,secret);address="http://"+bind.getHostAddress()+":18764/";server.start();instance=CompanionService.this;registerReceiver(connectivity,new IntentFilter(android.net.ConnectivityManager.CONNECTIVITY_ACTION));registered=true;timer.postDelayed(new Runnable(){public void run(){stopSelf();}},15*60000);}catch(Exception e){getSharedPreferences("companion",0).edit().putString("error",e.getMessage()).apply();stopSelf();}return START_NOT_STICKY;}
 public void onDestroy(){instance=null;timer.removeCallbacksAndMessages(null);if(registered)unregisterReceiver(connectivity);if(server!=null)server.close();secret="";stopForeground(true);super.onDestroy();}
}
